Can you instead add event listeners to the elements you want:

```js
document.querySelectorAll('.click-analytics').forEach(element =>
  element.addEventListener('click', e => {
    let correct_position = 1 + parseInt(e.target.getAttribute('data-position'));
    window.aa('click', {
      objectID: e.target.getAttribute('data-objectid'),
      position: correct_position,
    });
    console.log(e.target.getAttribute('data-objectid'));
  })
);

document.querySelectorAll('.conversion-analytics').forEach(element =>
  element.addEventListener('click', e => {
    window.aa('conversion', {
      objectID: e.target.getAttribute('data-objectid'),
    });
    console.log(e.target.getAttribute('data-objectid'));
  })
);
```
